376	// CloseShift 结束班次。任一接班交接存在未确认接收的事项（待处理、退回、
377	// 处理结果缺失或无法识别）时不允许结束，其他交接已完成也不能放行；空清单
378	// 交接视为已完成，可以结束。
379	// 结束成功时把在班事项（本班新增与已接收，含结束前已关闭者）冻结为结束时记录；
380	// 校验或保存失败时不留下任何记录，班次保持进行中，也不改变交接结果、
381	// 事项归属与已保存的处理经过。
382	func (svc *Service) CloseShift(shiftID string) (Shift, error) {
383		shiftID = clean(shiftID)
384		var result Shift
385		err := svc.store.mutate(func(d *Data) error {
386			sh, _ := findShift(d, shiftID)
387			if sh == nil {
388				return fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
389			}
390			if sh.Closed {
391				return fmt.Errorf("%w：班次 %s 已结束", ErrShiftClosed, sh.ID)
392			}
393			for i := range d.Handovers {
394				h := &d.Handovers[i]
395				if h.ToShiftID == sh.ID && !h.Completed() {
396					return fmt.Errorf("%w：接班交接 %s 仍有未确认接收的事项，班次不能结束",
397						ErrHandoverState, h.ID)
398				}
399			}
400			now := svc.now()
401			sh.Closed = true
402			sh.ClosedAt = &now
403	
404			// 冻结结束时在班的全部事项。退回或未确认的交接事项当前班次仍在交班
405			// 班次，不会被快照；结束前已关闭的事项保留关闭人与关闭时间。
406			record := &ShiftCloseRecord{Items: []CloseItemSnapshot{}}
407			for i := range d.Items {
408				it := &d.Items[i]
409				if it.CurrentShiftID != sh.ID {
410					continue
411				}
412				record.Items = append(record.Items, CloseItemSnapshot{
413					ItemID:        it.ID,
414					Content:       it.Content,
415					Severity:      it.Severity,
416					Constraints:   it.Constraints,
417					FollowOwner:   it.FollowOwner,
418					Closed:        it.Closed,
419					ClosedAt:      it.ClosedAt,
420					CloseOperator: it.CloseOperator,
421				})
422			}
423			sort.Slice(record.Items, func(i, j int) bool { return record.Items[i].ItemID < record.Items[j].ItemID })
424			sh.CloseRecord = record
425	
426			result = *sh
427			return nil
428		})
429		return result, err
430	}
