449		}
450		_, err = f.svc.CreateHandover(a.ID, d.ID)
451		if !errors.Is(err, ErrHandoverTarget) || !strings.Contains(err.Error(), b.ID) {
452			t.Fatalf("改换为已结束班次应报 ErrHandoverTarget 并指出原接班班次 %s，got %v", b.ID, err)
453		}
454	
455		// 改换为尚未结束的其他班次同样拒绝。
456		open := mustShift(t, f, "调度", "孙八", tsDay(3, 16, 0), tsDay(4, 0, 0), "")
457		if _, err := f.svc.CreateHandover(a.ID, open.ID); !errors.Is(err, ErrHandoverTarget) {
458			t.Fatalf("改换为未结束班次也应报 ErrHandoverTarget，got %v", err)
