461		otherPos := mustShift(t, f, "巡检", "周九", tsDay(3, 8, 0), tsDay(3, 16, 0), "")
462		if _, err := f.svc.CreateHandover(a.ID, otherPos.ID); !errors.Is(err, ErrHandoverTarget) {
463			t.Fatalf("已有交接时改指其他岗位应按改换对象拒绝，got %v", err)
464		}
