1643	// 重新提交与后续处理、完成状态在重开后均保留。
1644	func TestReturnedStatePersistsAcrossReopen(t *testing.T) {
1645		f := newFixture(t)
1646		a, b, items := prepareHandover(t, f)
1647		h, _ := f.svc.CreateHandover(a.ID, b.ID)
1648		idA, idB := items[0].ID, items[1].ID
1649		if _, err := f.svc.ProcessEntry(h.ID, idA, ActionReturn, "李四", "需补充", "", ""); err != nil {
1650			t.Fatalf("return: %v", err)
1651		}
1652		if _, err := f.svc.ProcessEntry(h.ID, idB, ActionConfirm, "李四", "", "", ""); err != nil {
1653			t.Fatalf("confirm: %v", err)
1654		}
1655	
1656		f.reopen(t)
1657		if _, err := f.svc.ProcessEntry(h.ID, idA, ActionReturn, "李四", "再退一轮", "", ""); !errors.Is(err, ErrHandoverState) {
1658			t.Fatalf("重开后未重新提交仍不能再次退回，got %v", err)
1659		}
1660		g, _ := f.svc.GetHandover(h.ID)
1661		e := findEntryOf(t, g, idA)
1662		if e.Status != EntryReturned || len(e.Rounds) != 1 || e.Operator != "李四" {
1663			t.Fatalf("重开后退回状态与轮次应原样保留：%+v", e)
1664		}
1665		if _, err := f.svc.ResubmitReturned(h.ID, idA, "张三", "补充材料"); err != nil {
1666			t.Fatalf("重开后应能补充重新提交：%v", err)
1667		}
1668	
1669		f.reopen(t)
1670		g, _ = f.svc.GetHandover(h.ID)
1671		e = findEntryOf(t, g, idA)
1672		if e.Status != EntryPending || e.Operator != "" || e.ProcessedAt != nil {
1673			t.Fatalf("重开后应保持待处理且尚未处理：%+v", e)
1674		}
1675		if _, err := f.svc.ProcessEntry(h.ID, idA, ActionConfirm, "李四", "", "", ""); err != nil {
1676			t.Fatalf("重开后应能确认接收：%v", err)
1677		}
1678		g, _ = f.svc.GetHandover(h.ID)
1679		if !g.Completed() {
1680			t.Fatalf("重开后续办完成应保留")
1681		}
1682	}
1683	
1684	// journeyKinds 提取处理经过的事件类型序列，便于断言顺序。
1685	func journeyKinds(j ItemJourney) []string {
1686		kinds := make([]string, len(j.Events))
1687		for i, ev := range j.Events {
1688			kinds[i] = ev.Kind
1689		}
1690		return kinds
1691	}
1692	
1693	func joinStrings(xs []string) string {
1694		out := ""
1695		for i, x := range xs {
1696			if i > 0 {
1697				out += ","
1698			}
1699			out += x
1700		}
1701		return out
1702	}
1703	
1704	// TestItemJourneyFullFlow：凭一个事项编号即可查看它从建立到当前、跨多个班次
1705	// 交接的完整处理经过，无须先知道交接编号；各次交接的当前结果一并列出。
1706	func TestItemJourneyFullFlow(t *testing.T) {
1707		f := newFixture(t)
1708		a := mustShift(t, f, "调度", "张三", tsDay(2, 8, 0), tsDay(2, 16, 0), "")
1709		b := mustShift(t, f, "调度", "李四", tsDay(2, 16, 0), tsDay(2, 23, 0), "")
1710		c := mustShift(t, f, "调度", "赵六", tsDay(2, 23, 0), tsDay(3, 7, 0), "")
1711		it, err := f.svc.AddItem(a.ID, "泵房压力异常", SeverityImportant, "夜间禁动", "李四")
1712		if err != nil {
1713			t.Fatalf("add item: %v", err)
1714		}
1715		// 同一交接里的另一事项，不应出现在本事项经过中。
1716		other, err := f.svc.AddItem(a.ID, "无关事项勿混入", SeverityNormal, "", "李四")
1717		if err != nil {
1718			t.Fatalf("add other: %v", err)
1719		}
1720		if _, err := f.svc.CloseShift(a.ID); err != nil {
1721			t.Fatalf("close a: %v", err)
1722		}
1723	
1724		h1, err := f.svc.CreateHandover(a.ID, b.ID)
1725		if err != nil {
1726			t.Fatalf("create h1: %v", err)
1727		}
1728		if _, err := f.svc.ProcessEntry(h1.ID, it.ID, ActionReturn, "李四", "缺少现场照片", "", ""); err != nil {
1729			t.Fatalf("return1: %v", err)
1730		}
1731		if _, err := f.svc.ResubmitReturned(h1.ID, it.ID, "张三", "照片已上传"); err != nil {
1732			t.Fatalf("resubmit1: %v", err)
1733		}
1734		if _, err := f.svc.ProcessEntry(h1.ID, it.ID, ActionReturn, "李四", "照片不清晰", "", ""); err != nil {
1735			t.Fatalf("return2: %v", err)
1736		}

