52	// writeItemHeader 输出事项的最新内容、严重程度、限制条件、后续负责人、
53	// 当前所在班次、关闭情况和流经班次。
54	func writeItemHeader(b *strings.Builder, it Item) {
55		state := "未关闭"
56		if it.Closed {
57			state = fmt.Sprintf("已关闭（%s 于 %s）", it.CloseOperator, fmtTimePtr(it.ClosedAt))
58		}
59		fmt.Fprintf(b, "%s  严重程度=%s  当前班次=%s  原始班次=%s  [%s]\n",
60			it.ID, it.Severity.Label(), it.CurrentShiftID, it.OriginShiftID, state)
61		fmt.Fprintf(b, "  内容：%s\n", it.Content)
62		fmt.Fprintf(b, "  限制条件：%s\n", dashIfEmpty(it.Constraints))
63		fmt.Fprintf(b, "  后续负责人：%s\n", it.FollowOwner)
64		fmt.Fprintf(b, "  流经班次：%s\n", strings.Join(it.ShiftIDs, " -> "))
65	}
66	
67	func dashIfEmpty(s string) string {
68		if s == "" {
69			return "-"
70		}
71		return s
72	}
73	
74	// whoIfRecorded 展示操作人，未记录时明确标为未记录，不以其他人代替。
75	func whoIfRecorded(s string) string {
76		if s == "" {
77			return "未记录"
78		}
79		return s
80	}
81	
82	// fmtTimePtrIfRecorded 展示时间指针，缺失时明确标为未记录。
83	func fmtTimePtrIfRecorded(t *time.Time) string {
84		if t == nil {
85			return "未记录"
86		}
87		return fmtTimeIfRecorded(*t)
88	}
89	
90	// fmtTimeIfRecorded 展示时间值，旧数据零值（0001-01-01T00:00:00Z）时
91	// 明确标为未记录，不显示公元元年日期。
92	func fmtTimeIfRecorded(t time.Time) string {
93		if t.IsZero() {
94			return "未记录"
95		}
96		return fmtTime(t)
97	}
98	
99	// fmtProcessedAtIfRecorded 展示处理时间，缺失（nil）或旧数据零值
100	// （0001-01-01T00:00:00Z）时明确标为未记录，不推测补齐。
101	func fmtProcessedAtIfRecorded(t *time.Time) string {
102		if t == nil || t.IsZero() {
103			return "未记录"
104		}
105		return fmtTime(*t)
106	}
107	
108	// currentProcessing 返回交接单项当前处理结果的处理人与处理时间展示，是
109	// 交接清单（handover-show、shift-show 内嵌清单与末尾结果说明）和事项处理
110	// 经过查询（item-show）共用的同一条业务规则。
111	//
112	// 是否处理过以已保存的处理结果（状态）为准，与处理时间是否保存无关：确认
113	// 接收、继续跟踪与退回都属于已经发生的处理，缺少处理时间不能使它们变成待
114	// 处理；真正待处理（含退回后已补充重新提交、等待接班人再次处理）的事项，
115	// 处理人与处理时间都显示尚未处理，即使旧记录残留姓名或时间也不显示成已处理。
116	//
117	// 已处理时处理人与处理时间各自独立展示：人名有值展示原姓名、缺失明确标为
118	// 未记录；时间有真实值沿用带时区格式、缺失或为旧数据零值
119	// （0001-01-01T00:00:00Z）同样标为未记录。缺少其中一个不能隐藏另一个，
120	// 也不以班次负责人、交接发起时间或退回历史中的信息代替。结果为空或无法
121	// 识别的记录同样按各自已保存的姓名与时间展示，不据以推测接收结果。
122	func currentProcessing(e HandoverEntry) (operator, processedAt string) {
123		if e.Status == EntryPending {
124			return "尚未处理", "尚未处理"
125		}
126		return whoIfRecorded(e.Operator), fmtProcessedAtIfRecorded(e.ProcessedAt)
127	}
128	
129	// entryCurrentResultLabel 是交接当前结果在事项处理经过查询中的展示名。
130	// 缺失或空结果显示“处理结果未记录”，无法识别的结果显示“处理结果无法识别”
131	// 并带出保存的原值，与交接清单、班次报告表达同一事实，不推测成已接收。
132	func entryCurrentResultLabel(s EntryStatus) string {
133		switch s {
134		case EntryPending:
135			return "待处理（接班人尚未处理）"
136		case EntryReturned:
137			return "退回（等待交班人补充）"
138		case EntryConfirmed:
139			return "确认接收"
140		case EntryTracking:
141			return "继续跟踪（已接收）"
142		case "":
143			return "处理结果未记录"
144		}
145		return "处理结果无法识别（原值：" + string(s) + "）"
146	}
147	
148	// FormatJourneyEvent 格式化处理经过中的单条记录。交接相关记录带有交接
149	// 编号与交班、接班班次；缺少的人名或时间明确标为未记录，不推测补齐。
150	func FormatJourneyEvent(ev JourneyEvent) string {
151		when := "未记录"
152		if ev.TimeKnown {
153			when = fmtTime(ev.At)
154		}
155		who := whoIfRecorded(ev.Operator)
156		where := ""
157		if ev.HandoverID != "" {
158			where = fmt.Sprintf("交接 %s（%s -> %s）", ev.HandoverID, ev.FromShift, ev.ToShift)
159		}
160		switch ev.Kind {
161		case "created":
162			return when + " 事项建立"
163		case "updated":
164			return fmt.Sprintf("%s 修改：%s", when, ev.Detail)
165		case "closed":
166			return fmt.Sprintf("%s 关闭 操作人=%s", when, who)
167		case "received":
168			return fmt.Sprintf("%s 接收 操作人=%s %s", when, who, ev.Detail)
169		case "handover-init":
170			// 交接发起不记录操作人，始终显示未记录，不以班次负责人代替。
171			return fmt.Sprintf("%s %s发起交接 操作人=%s", when, where, who)
172		case "return":
173			return fmt.Sprintf("%s %s第%d次退回 操作人=%s 原因=%s",
174				when, where, ev.RoundSeq, who, ev.Reason)
175		case "return-incomplete":
176			// 当前结果是退回却没有退回轮次记录：退回确实发生过，但轮次序号、
177			// 退回原因、补充与重新提交经过都没有可靠记录。处理人与时间各自使用
178			// 当前保存的信息（缺失分别标为未记录），并明确提示退回历史不完整、
179			// 原因未记录，不编造第几次退回，也不拿事项内容代替原因。
180			return fmt.Sprintf("%s %s退回 操作人=%s（退回历史不完整：缺少退回轮次记录，退回原因未记录）",
181				when, where, who)
182		case "resubmit":
183			return fmt.Sprintf("%s %s第%d次重新提交 补充说明=%s 补充人=%s 补充时间=%s",
184				when, where, ev.RoundSeq, dashIfEmpty(ev.Supplement),
185				whoIfRecorded(ev.SupplementOperator), fmtTimePtrIfRecorded(ev.SupplementAt))
186		case "confirm":
187			return fmt.Sprintf("%s %s确认接收 操作人=%s", when, where, who)
188		case "track":
189			return fmt.Sprintf("%s %s继续跟踪 操作人=%s 跟踪说明=%s 后续负责人=%s",
190				when, where, who, dashIfEmpty(ev.TrackingNote), dashIfEmpty(ev.FollowOwner))
191		}
192		return when + " " + ev.Kind
193	}
