224	// FormatCloseItem 格式化班次结束时冻结的事项记录，并与最新状态对照。
225	func FormatCloseItem(snap CloseItemSnapshot, latest *Item) string {
226		var b strings.Builder
227		state := "结束时未关闭"
228		if snap.Closed {
229			state = fmt.Sprintf("结束时已关闭（%s 于 %s）", snap.CloseOperator, fmtTimePtr(snap.ClosedAt))
230		}
231		fmt.Fprintf(&b, "%s  严重程度=%s  %s\n", snap.ItemID, snap.Severity.Label(), state)
232		fmt.Fprintf(&b, "  内容：%s\n", snap.Content)
233		fmt.Fprintf(&b, "  限制条件：%s\n", dashIfEmpty(snap.Constraints))
234		fmt.Fprintf(&b, "  结束时后续负责人：%s\n", snap.FollowOwner)
235		if latest == nil {
236			b.WriteString("  最新状态：事项记录已不存在\n")
237			return b.String()
238		}
239		closeState := "未关闭"
240		if latest.Closed {
241			closeState = fmt.Sprintf("已关闭（%s 于 %s）", latest.CloseOperator, fmtTimePtr(latest.ClosedAt))
242		}
243		fmt.Fprintf(&b, "  最新状态：当前所在班次=%s  最新负责人=%s  最新关闭情况=%s\n",
244			latest.CurrentShiftID, latest.FollowOwner, closeState)
245		return b.String()
246	}
