248	// FormatOverlapNote 格式化重叠说明。
249	func FormatOverlapNote(n OverlapNote) string {
250		return fmt.Sprintf("%s  岗位=%s  班次 %s <-> %s  %s\n  说明：%s",
251			n.ID, n.Position, n.ShiftA, n.ShiftB, fmtTime(n.CreatedAt), n.Note)
252	}
