254	// FormatEntry 格式化交接单项当前结果与历次退回、补充说明。
255	func FormatEntry(e HandoverEntry) string {
256		var b strings.Builder
257		fmt.Fprintf(&b, "%s  [%s]  严重程度=%s  后续负责人=%s\n",
258			e.ItemID, e.Status.Label(), e.Severity.Label(), e.FollowOwner)
259		fmt.Fprintf(&b, "  原文：%s\n", e.Content)
260		fmt.Fprintf(&b, "  限制条件：%s\n", dashIfEmpty(e.Constraints))
261		// 处理人与处理时间沿用共用的当前处理展示规则（见 currentProcessing）；
262		// 待处理项在此额外说明等待接班人处理。
263		operator, processedAt := currentProcessing(e)
264		if e.Status == EntryPending {
265			fmt.Fprintf(&b, "  最后处理：尚未处理（等待接班人处理）；处理人=%s；处理时间=%s\n",
266				operator, processedAt)
267		} else {
268			fmt.Fprintf(&b, "  最后处理：处理人=%s；处理时间=%s\n", operator, processedAt)
269		}
270		if e.Status == EntryTracking || e.TrackingNote != "" {
271			fmt.Fprintf(&b, "  跟踪说明：%s\n", dashIfEmpty(e.TrackingNote))
272			fmt.Fprintf(&b, "  跟踪后续负责人：%s\n", dashIfEmpty(e.FollowOwner))
273		}
274		for _, r := range e.Rounds {
275			fmt.Fprintf(&b, "  第%d次退回：%s 操作人=%s 原因=%s\n",
276				r.Seq, fmtTimeIfRecorded(r.ReturnedAt),
277				whoIfRecorded(r.ReturnOperator), r.Reason)
278			if r.Supplement != "" {
279				fmt.Fprintf(&b, "    补充说明：%s 补充人=%s 补充时间=%s\n",
280					r.Supplement, whoIfRecorded(r.SupplementOperator),
281					fmtTimePtrIfRecorded(r.SupplementAt))
282			}
283			if r.ResubmittedAt != nil {
284				fmt.Fprintf(&b, "    已重新提交：%s\n", fmtTimePtrIfRecorded(r.ResubmittedAt))
285			}
286		}
287		return b.String()
288	}
