290	// FormatHandover 格式化完整交接记录。
291	func FormatHandover(h Handover) string {
292		var b strings.Builder
293		state := "未完成"
294		if h.Completed() {
295			state = "已完成 " + fmtTimePtrIfRecorded(h.CompletedAt)
296		}
297		fmt.Fprintf(&b, "%s  岗位=%s  %s -> %s  发起于 %s  [%s]  共%d项\n",
298			h.ID, h.Position, h.FromShiftID, h.ToShiftID,
299			fmtTimeIfRecorded(h.CreatedAt), state, len(h.Entries))
300		if len(h.Entries) == 0 {
301			b.WriteString("  （空清单，直接完成）\n")
302		}
303		for i := range h.Entries {
304			b.WriteString(indentLines(FormatEntry(h.Entries[i]), "  "))
305		}
306		return b.String()
307	}
